window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-37505a5c50d55ccb"]={"versions": [{"id": "FIG-37505a5c50d55ccb", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm bzw. Dekompositionsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure für Methodenaktivitäten). Das Diagramm stellt die hierarchische Schachtelung und Zerlegung der übergeordneten Aktivität <code>Generate BSW and RTE</code> in funktionale Teilaktivitäten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität (Composite Activity / Process Step) <code>Generate BSW and RTE</code>. Über ungerichtete Aggregationsbeziehungen mit dem Stereotyp <code>«nesting»</code> (Raute an der übergeordneten Aktivität) sind sieben atomare Aktivitäten untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>Generate SWC Memory Mapping Header</code>\n</li><li><code>Generate OS</code>\n</li><li><code>Generate Local MC Data Support</code>\n</li><li><code>Generate RTE</code>\n</li><li><code>Generate RTE Prebuild Dataset</code>\n</li><li><code>Generate BSW Memory Mapping Header</code>\n</li><li><code>Generate BSW Configuration Code</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein strukturelle hierarchische Dekomposition (Nesting / Aggregation) ohne expliziten Kontroll- oder Datenfluss. Es sind keine Sequenzkanten, Startereignisse, Endzustände oder Bedingungszweige definiert; die Ausführung der Teilaktivitäten erfolgt im Rahmen des übergeordneten Generierungsprozesses für BSW und RTE gemäß deren jeweiligen Datenabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Leitlinie für Generatorenwerkzeuge in der BSW- und RTE-Erstellung: Die Generierung gliedert sich in spezialisierte Teilaufgaben für Memory Mapping Header von SWC und BSW, Konfigurationscode der Basissoftware, OS-Generierung, RTE-Artefakte und Prebuild-Datensätze sowie lokale MC-Datenunterstützung. Werkzeuge müssen die Erzeugung dieser Artefakte modular abbilden.</p>"}, {"id": "FIG-c61065da47a5535a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm bzw. Dekompositionsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure für Methodenaktivitäten). Das Diagramm stellt die hierarchische Schachtelung und Zerlegung der übergeordneten Aktivität <code>Generate BSW and RTE</code> in funktionale Teilaktivitäten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität <code>Generate BSW and RTE</code>. Über <code>«nesting»</code>-Aggregationsbeziehungen sind acht atomare Aktivitäten untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>Generate SWC Memory Mapping Header</code>\n</li><li><code>Generate OS</code>\n</li><li><code>Generate Local MC Data Support</code>\n</li><li><code>Generate RTE</code>\n</li><li><code>Generate RTE Prebuild Dataset</code>\n</li><li><code>Generate BSW Memory Mapping Header</code>\n</li><li><code>Generate Compiler Configuration</code>\n</li><li><code>Generate BSW Configuration Code</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein strukturelle hierarchische Dekomposition (Nesting / Aggregation) ohne expliziten Kontroll- oder Datenfluss. Es sind keine Sequenzkanten, Startereignisse, Endzustände oder Bedingungszweige definiert; die Ausführung der Teilaktivitäten erfolgt im Rahmen des übergeordneten Generierungsprozesses für BSW und RTE gemäß deren jeweiligen Datenabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Vorgabe für die Werkzeugkette: Der Generierungsschritt von BSW und RTE umfasst neben BSW-Code, RTE- und OS-Generierung sowie Memory-Mapping-Headern auch die dezidierte Teilaktivität <code>Generate Compiler Configuration</code> zur Erzeugung compilerspezifischer Konfigurationen.</p>"}, {"id": "FIG-e70c59a17732a340", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm bzw. Dekompositionsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure für Methodenaktivitäten). Das Diagramm stellt die hierarchische Schachtelung und Zerlegung der übergeordneten Aktivität <code>Generate BSW and RTE</code> in funktionale Teilaktivitäten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität <code>Generate BSW and RTE</code>. Über <code>«nesting»</code>-Aggregationsbeziehungen sind acht atomare Aktivitäten untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>Generate SWC Memory Mapping Header</code>\n</li><li><code>Generate OS</code>\n</li><li><code>Generate Local MC Data Support</code>\n</li><li><code>Generate RTE</code>\n</li><li><code>Generate RTE Prebuild Dataset</code>\n</li><li><code>Generate BSW Memory Mapping Header</code>\n</li><li><code>Generate Compiler Configuration</code>\n</li><li><code>Generate BSW Configuration Code</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein strukturelle hierarchische Dekomposition (Nesting / Aggregation) ohne expliziten Kontroll- oder Datenfluss. Es sind keine Sequenzkanten, Startereignisse, Endzustände oder Bedingungszweige definiert; die Ausführung der Teilaktivitäten erfolgt im Rahmen des übergeordneten Generierungsprozesses für BSW und RTE gemäß deren jeweiligen Datenabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Vorgabe für die Werkzeugkette: Der Generierungsschritt von BSW und RTE umfasst neben BSW-Code, RTE- und OS-Generierung sowie Memory-Mapping-Headern auch die dezidierte Teilaktivität <code>Generate Compiler Configuration</code> zur Erzeugung compilerspezifischer Konfigurationen.</p>"}, {"id": "FIG-31dc2285e84a7486", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm bzw. Dekompositionsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure für Methodenaktivitäten). Das Diagramm stellt die hierarchische Schachtelung und Zerlegung der übergeordneten Aktivität <code>Generate BSW and RTE</code> in funktionale Teilaktivitäten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität <code>Generate BSW and RTE</code>. Über <code>«nesting»</code>-Aggregationsbeziehungen sind acht atomare Aktivitäten untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>Generate SWC Memory Mapping Header</code>\n</li><li><code>Generate OS</code>\n</li><li><code>Generate Local MC Data Support</code>\n</li><li><code>Generate RTE</code>\n</li><li><code>Generate RTE Prebuild Dataset</code>\n</li><li><code>Generate BSW Memory Mapping Header</code>\n</li><li><code>Generate Compiler Configuration</code>\n</li><li><code>Generate BSW Configuration Code</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein strukturelle hierarchische Dekomposition (Nesting / Aggregation) ohne expliziten Kontroll- oder Datenfluss. Es sind keine Sequenzkanten, Startereignisse, Endzustände oder Bedingungszweige definiert; die Ausführung der Teilaktivitäten erfolgt im Rahmen des übergeordneten Generierungsprozesses für BSW und RTE gemäß deren jeweiligen Datenabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Vorgabe für die Werkzeugkette: Der Generierungsschritt von BSW und RTE umfasst neben BSW-Code, RTE- und OS-Generierung sowie Memory-Mapping-Headern auch die dezidierte Teilaktivität <code>Generate Compiler Configuration</code> zur Erzeugung compilerspezifischer Konfigurationen.</p>"}, {"id": "FIG-69fcfa54641d2cae", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm bzw. Dekompositionsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure für Methodenaktivitäten). Das Diagramm stellt die hierarchische Schachtelung und Zerlegung der übergeordneten Aktivität <code>Generate BSW and RTE</code> in funktionale Teilaktivitäten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität <code>Generate BSW and RTE</code>. Über <code>«nesting»</code>-Aggregationsbeziehungen sind acht atomare Aktivitäten untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>Generate SWC Memory Mapping Header</code>\n</li><li><code>Generate OS</code>\n</li><li><code>Generate Local MC Data Support</code>\n</li><li><code>Generate RTE</code>\n</li><li><code>Generate RTE Prebuild Dataset</code>\n</li><li><code>Generate BSW Memory Mapping Header</code>\n</li><li><code>Generate Compiler Configuration</code>\n</li><li><code>Generate BSW Configuration Code</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein strukturelle hierarchische Dekomposition (Nesting / Aggregation) ohne expliziten Kontroll- oder Datenfluss. Es sind keine Sequenzkanten, Startereignisse, Endzustände oder Bedingungszweige definiert; die Ausführung der Teilaktivitäten erfolgt im Rahmen des übergeordneten Generierungsprozesses für BSW und RTE gemäß deren jeweiligen Datenabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Vorgabe für die Werkzeugkette: Der Generierungsschritt von BSW und RTE umfasst neben BSW-Code, RTE- und OS-Generierung sowie Memory-Mapping-Headern auch die dezidierte Teilaktivität <code>Generate Compiler Configuration</code> zur Erzeugung compilerspezifischer Konfigurationen.</p>"}, {"id": "FIG-7b494f49fa9c1811", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm bzw. Dekompositionsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure für Methodenaktivitäten). Das Diagramm stellt die hierarchische Schachtelung und Zerlegung der übergeordneten Aktivität <code>Generate BSW and RTE</code> in funktionale Teilaktivitäten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität <code>Generate BSW and RTE</code>. Über <code>«nesting»</code>-Aggregationsbeziehungen sind sieben atomare Aktivitäten untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>Generate SWC Memory Mapping Header</code>\n</li><li><code>Generate OS</code>\n</li><li><code>Generate Local MC Data Support</code>\n</li><li><code>Generate RTE</code> (im Diagrammlayout als <code>Generate</code> dargestellt)\n</li><li><code>Generate RTE Prebuild Dataset</code>\n</li><li><code>Generate BSW Memory Mapping Header</code>\n</li><li><code>Generate BSW Configuration Code</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein strukturelle hierarchische Dekomposition (Nesting / Aggregation) ohne expliziten Kontroll- oder Datenfluss. Es sind keine Sequenzkanten, Startereignisse, Endzustände oder Bedingungszweige definiert; die Ausführung der Teilaktivitäten erfolgt im Rahmen des übergeordneten Generierungsprozesses für BSW und RTE gemäß deren jeweiligen Datenabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Vorgabe für die BSW- und RTE-Generierung: Die Aktivität <code>Generate Compiler Configuration</code> ist nicht Bestandteil der Zerlegung von <code>Generate BSW and RTE</code>. Die Compiler-Konfiguration wird außerhalb dieses spezifischen Generierungsschritts gehandhabt.</p>"}, {"id": "FIG-3f100712cae9aac9", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm bzw. Dekompositionsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure für Methodenaktivitäten). Das Diagramm stellt die hierarchische Schachtelung und Zerlegung der übergeordneten Aktivität <code>Generate BSW and RTE</code> in funktionale Teilaktivitäten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität <code>Generate BSW and RTE</code>. Über <code>«nesting»</code>-Aggregationsbeziehungen sind sieben atomare Aktivitäten untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>Generate SWC Memory Mapping Header</code>\n</li><li><code>Generate OS</code>\n</li><li><code>Generate Local MC Data Support</code>\n</li><li><code>Generate RTE</code> (im Diagrammlayout als <code>Generate</code> dargestellt)\n</li><li><code>Generate RTE Prebuild Dataset</code>\n</li><li><code>Generate BSW Memory Mapping Header</code>\n</li><li><code>Generate BSW Configuration Code</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein strukturelle hierarchische Dekomposition (Nesting / Aggregation) ohne expliziten Kontroll- oder Datenfluss. Es sind keine Sequenzkanten, Startereignisse, Endzustände oder Bedingungszweige definiert; die Ausführung der Teilaktivitäten erfolgt im Rahmen des übergeordneten Generierungsprozesses für BSW und RTE gemäß deren jeweiligen Datenabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Vorgabe für die BSW- und RTE-Generierung: Die Aktivität <code>Generate Compiler Configuration</code> ist nicht Bestandteil der Zerlegung von <code>Generate BSW and RTE</code>. Die Compiler-Konfiguration wird außerhalb dieses spezifischen Generierungsschritts gehandhabt.</p>"}, {"id": "FIG-18e9bbbdd51d45bb", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm bzw. Dekompositionsdiagramm der AUTOSAR-Methodik (Work Breakdown Structure für Methodenaktivitäten). Das Diagramm stellt die hierarchische Schachtelung und Zerlegung der übergeordneten Aktivität <code>Generate BSW and RTE</code> in funktionale Teilaktivitäten dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrale Entität ist die zusammengesetzte Aktivität <code>Generate BSW and RTE</code>. Über <code>«nesting»</code>-Aggregationsbeziehungen sind sieben atomare Aktivitäten untergeordnet:</p>\n<ul class=\"fig-list\"><li><code>Generate SWC Memory Mapping Header</code>\n</li><li><code>Generate OS</code>\n</li><li><code>Generate Local MC Data Support</code>\n</li><li><code>Generate RTE</code> (im Diagrammlayout als <code>Generate</code> dargestellt)\n</li><li><code>Generate RTE Prebuild Dataset</code>\n</li><li><code>Generate BSW Memory Mapping Header</code>\n</li><li><code>Generate BSW Configuration Code</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm spezifiziert eine rein strukturelle hierarchische Dekomposition (Nesting / Aggregation) ohne expliziten Kontroll- oder Datenfluss. Es sind keine Sequenzkanten, Startereignisse, Endzustände oder Bedingungszweige definiert; die Ausführung der Teilaktivitäten erfolgt im Rahmen des übergeordneten Generierungsprozesses für BSW und RTE gemäß deren jeweiligen Datenabhängigkeiten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Methodische Vorgabe für die BSW- und RTE-Generierung: Die Aktivität <code>Generate Compiler Configuration</code> ist nicht Bestandteil der Zerlegung von <code>Generate BSW and RTE</code>. Die Compiler-Konfiguration wird außerhalb dieses spezifischen Generierungsschritts gehandhabt.</p>"}], "trans": [{"from": "FIG-37505a5c50d55ccb", "to": "FIG-c61065da47a5535a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Hinzufügung der Aktivität <code>Generate Compiler Configuration</code> über eine mit «nesting» stereotyptierte Aggregationsbeziehung an der übergeordneten Aktivität <code>Generate BSW and RTE</code>.\n</li></ul>"}, {"from": "FIG-c61065da47a5535a", "to": "FIG-e70c59a17732a340", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e70c59a17732a340", "to": "FIG-31dc2285e84a7486", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Umbruch des Beschriftungstextes der zentralen Aktivität von <code>Generate BSW and RTE</code> zu zweizeiligem <code>Generate BSW and</code> / <code>RTE</code>.\n</li></ul>"}, {"from": "FIG-31dc2285e84a7486", "to": "FIG-69fcfa54641d2cae", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-69fcfa54641d2cae", "to": "FIG-7b494f49fa9c1811", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Entfernung der Aktivität <code>Generate Compiler Configuration</code> und der zugehörigen «nesting»-Aggregationsbeziehung.\n</li><li>Textabrisse/Layoutfehler bei Aktivitätsbezeichnungen: <code>Generate RTE</code> ist am unteren Rand zu <code>Generate</code> abgeschnitten, <code>Generate Local MC Data Support</code> ist zu <code>Generate Local</code> / <code>MC Data Support</code> umbrochen.\n</li></ul>"}, {"from": "FIG-7b494f49fa9c1811", "to": "FIG-3f100712cae9aac9", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Vertikaler Beschnitt des Bildausschnitts am unteren Rand: Die unteren Beschriftungszeilen von <code>Generate Local [MC Data Support]</code>, <code>Generate [RTE]</code>, <code>Generate RTE [Prebuild Dataset]</code> und <code>Generate BSW [Memory Mapping Header]</code> sowie der Aktivitätsname der zentralen Aktivität (<code>Generate BSW and</code> / <code>RTE</code> zu nur <code>RTE</code>) sind abgeschnitten.\n</li></ul>"}, {"from": "FIG-3f100712cae9aac9", "to": "FIG-18e9bbbdd51d45bb", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
